CREATE TABLE IF NOT EXISTS receipt_game_monster (monster_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_table_name VARCHAR(64) NOT NULL UNIQUE, image_sha256 VARCHAR(64) NOT NULL UNIQUE, monster_name VARCHAR(120) NOT NULL, species VARCHAR(30) NOT NULL, rarity VARCHAR(30) NOT NULL, power INTEGER NOT NULL, guard INTEGER NOT NULL, speed INTEGER NOT NULL, generation_status VARCHAR(20) NOT NULL, generation_started_at TIMESTAMP WITH TIME ZONE, monster_image BYTEA, monster_image_mime_type VARCHAR(50), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_game_monster_receipt FOREIGN KEY (receipt_table_name) REFERENCES receipt_structured_summary(receipt_table_name) ON DELETE CASCADE, CONSTRAINT ck_game_monster_status CHECK (generation_status IN ('GENERATING','READY','FAILED')), CONSTRAINT ck_game_monster_ready_image CHECK (generation_status <> 'READY' OR (monster_image IS NOT NULL AND monster_image_mime_type = 'image/jpeg')));
CREATE TABLE IF NOT EXISTS receipt_game_room (room_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_code VARCHAR(6) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL, player1_name VARCHAR(20) NOT NULL, player2_name VARCHAR(20), player1_token_hash VARCHAR(64) NOT NULL, player2_token_hash VARCHAR(64), player1_candidate_receipt_table_names TEXT[] NOT NULL DEFAULT '{}', player2_candidate_receipt_table_names TEXT[] NOT NULL DEFAULT '{}', player1_selected_monster_id BIGINT, player2_selected_monster_id BIGINT, player1_locked BOOLEAN NOT NULL DEFAULT FALSE, player2_locked BOOLEAN NOT NULL DEFAULT FALSE, player1_battle_score_x2 BIGINT, player2_battle_score_x2 BIGINT, winner_player VARCHAR(8), winner_monster_id BIGINT, battle_completed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, last_activity_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_room_player1_monster FOREIGN KEY (player1_selected_monster_id) REFERENCES receipt_game_monster(monster_id) ON DELETE SET NULL, CONSTRAINT fk_room_player2_monster FOREIGN KEY (player2_selected_monster_id) REFERENCES receipt_game_monster(monster_id) ON DELETE SET NULL, CONSTRAINT fk_room_winner_monster FOREIGN KEY (winner_monster_id) REFERENCES receipt_game_monster(monster_id) ON DELETE SET NULL, CONSTRAINT ck_game_room_status CHECK (status IN ('WAITING_PLAYER2','SELECTING','PLAYER1_LOCKED','PLAYER2_LOCKED','BOTH_READY','BATTLE_COMPLETE','ABANDONED')), CONSTRAINT ck_game_room_winner CHECK (winner_player IS NULL OR winner_player IN ('PLAYER1','PLAYER2')));
CREATE INDEX IF NOT EXISTS idx_receipt_game_room_expires_at ON receipt_game_room(expires_at);
